26:      --listen-addr=0.0.0.0:26257 \
27:      --advertise-addr=antigravity-server:26257 \
28:      --join=0.0.0.0:26257,39.mh:26257,38.mh:26257,201.mh:26257,aurora-r0:26257 \
29:      --background
