Gofunc ComputeProteinStates(    proteins []ProteinAgent,    z []float64,) []ProteinState {    var states []ProteinState    for _, p := range proteins {        activation := dot(p.Beta, z)        state := ProteinState{            ID:              p.ID,            Activation:      max(0, activation),            Stability:       1.0,            BindingAffinity: 1.0,        }        states = append(states, state)    }    return states}Show more lines

