Gofunc ApplyNutrientConstraints(    states []ProteinState,    proteins []ProteinAgent,    nutrients map[string]float64,) {    for i := range states {        p := proteins[i]        state := &states[i]        for _, dep := range p.Nutrients {            level := nutrients[dep.Nutrient]            if level < 0.5 {                state.Activation *= dep.ActivationEffect                state.Stability *= dep.StabilityEffect                state.BindingAffinity *= dep.BindingEffect            }        }    }}Show more lines

