Gofunc ComputeTissueImpact(    states []ProteinState,    proteins []ProteinAgent,) map[string]float64 {    result := make(map[string]float64)    for i, state := range states {        p := proteins[i]        for tissue, expr := range p.Tissues {            result[tissue] += state.Activation * expr        }    }    return result}Show more lines

